import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String dnaSequence = scanner.next();
        int countPairs = 0, currentCount = 1;
        char lastChar = dnaSequence.charAt(0);
        for (int index = 1; index < dnaSequence.length(); index++) {
            if (lastChar == dnaSequence.charAt(index)) {
                currentCount++;
                lastChar = dnaSequence.charAt(index);
                if (index != dnaSequence.length() - 1) {
                    if (dnaSequence.charAt(index + 1) != lastChar && currentCount % 2 == 0) {
                        countPairs++;
                        currentCount = 1;
                    }
                } else if (currentCount % 2 == 0) {
                    countPairs++;
                    currentCount = 1;
                }
            } else {
                lastChar = dnaSequence.charAt(index);
            }
        }
        System.out.println(countPairs);
    }
}
